
        // Version de l'app — si différente du serveur, force reload
        const APP_VERSION = '20260415b';
        (async function checkVersion() {
            try {
                const resp = await fetch('/app-version.txt?t=' + Date.now(), { cache: 'no-store' });
                if (resp.ok) {
                    const serverVersion = (await resp.text()).trim();
                    if (serverVersion && serverVersion !== APP_VERSION) {
                        console.log('New version detected:', serverVersion, '!= ', APP_VERSION);
                        // Mettre à jour le SW sans le désinstaller (nécessaire pour Share Target)
                        if ('serviceWorker' in navigator) {
                            const regs = await navigator.serviceWorker.getRegistrations();
                            for (const r of regs) await r.update();
                        }
                        window.location.reload(true);
                        return;
                    }
                }
            } catch(e) {}
        })();

        // Fonction utilitaire : charger TOUS les bons depuis Firestore
        let _bonsCache = null;
        let _bonsCacheTime = 0;
        async function loadBonsFromFirestore(forceRefresh) {
            // Cache mémoire 2min — empêche les requêtes répétées dans la même session
            if (!forceRefresh && _bonsCache && (Date.now() - _bonsCacheTime < 120000)) return _bonsCache;
            const db = firebase.firestore();
            // Vérifier le compteur serveur pour détecter si les données ont changé
            try {
                const meta = await db.collection('app_settings').doc('pfq_import_meta').get();
                const serverCount = meta.exists ? (meta.data().lastImportCount || 0) : 0;
                if (_bonsCache && _bonsCache.length === serverCount && (Date.now() - _bonsCacheTime < 300000)) {
                    console.log('[Firestore] Cache valid, count matches server:', serverCount);
                    return _bonsCache;
                }
            } catch(e) {}
            // Charger depuis Firestore
            const snap = await db.collection('pfq_interne').get();
            const allBons = snap.docs.map(d => ({ id: d.id, ...d.data() }));
            _bonsCache = allBons;
            _bonsCacheTime = Date.now();
            console.log('[Firestore] Loaded', allBons.length, 'bons from', snap.metadata.fromCache ? 'CACHE' : 'SERVER');
            // Si les données viennent du cache et ne matchent pas le compteur serveur, forcer un refresh
            if (snap.metadata.fromCache) {
                try {
                    const meta = await db.collection('app_settings').doc('pfq_import_meta').get();
                    const serverCount = meta.exists ? (meta.data().lastImportCount || 0) : 0;
                    if (serverCount > 0 && allBons.length < serverCount * 0.95) {
                        console.log('[Firestore] Cache stale! Got', allBons.length, 'expected ~', serverCount, '- waiting for server...');
                        // Attendre que Firestore synchro avec le serveur
                        await db.waitForPendingWrites();
                        const snap2 = await db.collection('pfq_interne').get();
                        const freshBons = snap2.docs.map(d => ({ id: d.id, ...d.data() }));
                        if (freshBons.length > allBons.length) {
                            _bonsCache = freshBons;
                            _bonsCacheTime = Date.now();
                            console.log('[Firestore] Refreshed to', freshBons.length, 'bons');
                            return freshBons;
                        }
                    }
                } catch(e) {}
            }
            return allBons;
        }

        // Error boundary pour capturer les erreurs React
        class ErrorBoundary extends React.Component {
            constructor(props) { super(props); this.state = { error: null, info: null }; }
            componentDidCatch(error, info) { this.setState({ error, info }); }
            render() {
                if (this.state.error) {
                    return React.createElement('pre', { style: { color: 'red', padding: 20, fontSize: 14, whiteSpace: 'pre-wrap' } },
                        'ERREUR REACT:\n' + this.state.error.toString() + '\n\n' + (this.state.info ? this.state.info.componentStack : ''));
                }
                return this.props.children;
            }
        }
        // Error boundary par onglet — isole les crashs pour que seul l'onglet cassé affiche une erreur
        class TabErrorBoundary extends React.Component {
            constructor(props) { super(props); this.state = { error: null, info: null }; }
            static getDerivedStateFromError(error) { return { error }; }
            componentDidCatch(error, info) { this.setState({ info }); console.error('[Tab:' + (this.props.name || '?') + ']', error); }
            render() {
                if (this.state.error) {
                    return React.createElement('div', { style: { padding: 40, textAlign: 'center' } },
                        React.createElement('i', { className: 'fa-solid fa-triangle-exclamation', style: { fontSize: 48, color: '#dc2626', marginBottom: 16 } }),
                        React.createElement('h3', { style: { margin: '16px 0 8px', color: '#1e293b' } }, 'Erreur dans : ' + (this.props.name || 'cet onglet')),
                        React.createElement('p', { style: { color: '#64748b', fontSize: 14, marginBottom: 16 } }, this.state.error.toString()),
                        React.createElement('button', {
                            onClick: () => this.setState({ error: null, info: null }),
                            style: { padding: '8px 20px', background: '#3b82f6', color: '#fff', border: 'none', borderRadius: 8, cursor: 'pointer', fontSize: 14 }
                        }, 'Réessayer'),
                        React.createElement('details', { style: { marginTop: 16, textAlign: 'left', maxWidth: 600, margin: '16px auto' } },
                            React.createElement('summary', { style: { cursor: 'pointer', color: '#94a3b8', fontSize: 12 } }, 'Détails techniques'),
                            React.createElement('pre', { style: { fontSize: 11, color: '#94a3b8', whiteSpace: 'pre-wrap', marginTop: 8 } }, this.state.info && this.state.info.componentStack)
                        )
                    );
                }
                return this.props.children;
            }
        }
        const { useState, useEffect, useMemo, useCallback, useRef } = React;

        // ===================== API CACHE (stale-while-revalidate + localStorage) =====================
        const _apiCache = {};
        // Patch fetch to auto-inject Firebase Auth token on /api/ calls
        const _origFetch = window.fetch;
        window.fetch = async function(url, opts) {
            if (typeof url === 'string' && url.startsWith('/api/')) {
                opts = opts || {};
                opts.headers = opts.headers || {};
                try {
                    if (firebaseAuth && firebaseAuth.currentUser) {
                        const token = await firebaseAuth.currentUser.getIdToken();
                        opts.headers['Authorization'] = 'Bearer ' + token;
                    }
                } catch(e) {}
            }
            return _origFetch.call(this, url, opts);
        };

        const CACHE_TTL = 5 * 60 * 1000; // 5 minutes
        function cachedFetch(url) {
            const now = Date.now();
            // 1. Memory cache hit (< 5 min)
            if (_apiCache[url] && (now - _apiCache[url].ts < CACHE_TTL)) {
                return Promise.resolve(_apiCache[url].data);
            }
            // 2. localStorage cache hit (< 5 min)
            try {
                const stored = localStorage.getItem('cache_' + url);
                if (stored) {
                    const parsed = JSON.parse(stored);
                    if (now - parsed.ts < CACHE_TTL) {
                        _apiCache[url] = { data: parsed.data, ts: parsed.ts };
                        return Promise.resolve(parsed.data);
                    }
                }
            } catch(e) {}
            // 3. Cache miss or expired — fetch fresh from network
            return fetch(url).then(r => r.json()).then(data => {
                _apiCache[url] = { data, ts: Date.now() };
                try { localStorage.setItem('cache_' + url, JSON.stringify({ data, ts: Date.now() })); } catch(e) {}
                return data;
            });
        }
        function invalidateCache(urlPattern) {
            // Clear memory cache
            Object.keys(_apiCache).forEach(k => {
                if (!urlPattern || k.includes(urlPattern)) delete _apiCache[k];
            });
            // Clear ALL localStorage cache entries (not just known keys)
            try {
                Object.keys(localStorage).forEach(k => {
                    if (k.startsWith('cache_') && (!urlPattern || k.includes(urlPattern))) localStorage.removeItem(k);
                });
            } catch(e) {}
        }

        // ===================== CUSTOM SVG CHARTS =====================
        function SimpleBarChart({ data, dataKeys, colors, xKey, height = 250 }) {
            if (!data || !data.length) return null;
            const padding = { top: 20, right: 20, bottom: 30, left: 40 };
            const maxVal = Math.max(...data.flatMap(d => dataKeys.map(k => d[k] || 0)));
            const barGroupWidth = 100 / data.length;
            const barWidth = barGroupWidth / (dataKeys.length + 1);

            return (
                React.createElement('svg', { width: '100%', height: height, viewBox: `0 0 600 ${height}`, preserveAspectRatio: 'xMidYMid meet' },
                    React.createElement('g', null,
                        [0, 0.25, 0.5, 0.75, 1].map((tick, i) => {
                            const y = padding.top + (height - padding.top - padding.bottom) * (1 - tick);
                            return React.createElement('g', { key: i },
                                React.createElement('line', { x1: padding.left, y1: y, x2: 600 - padding.right, y2: y, stroke: '#f0f0f0', strokeDasharray: '3 3' }),
                                React.createElement('text', { x: padding.left - 5, y: y + 4, textAnchor: 'end', fontSize: '10', fill: '#999' }, Math.round(maxVal * tick))
                            );
                        }),
                        data.map((d, di) => {
                            const groupX = padding.left + (di / data.length) * (600 - padding.left - padding.right);
                            const groupW = (600 - padding.left - padding.right) / data.length;
                            return React.createElement('g', { key: di },
                                dataKeys.map((key, ki) => {
                                    const val = d[key] || 0;
                                    const barH = (val / (maxVal || 1)) * (height - padding.top - padding.bottom);
                                    const bw = groupW / (dataKeys.length + 1);
                                    const bx = groupX + (ki + 0.5) * bw;
                                    const by = padding.top + (height - padding.top - padding.bottom) - barH;
                                    return React.createElement('rect', { key: ki, x: bx, y: by, width: bw * 0.8, height: barH, fill: colors[ki % colors.length], rx: '4', opacity: '0.85', title: `${key}: ${val}` });
                                }),
                                React.createElement('text', { x: groupX + groupW / 2, y: height - 8, textAnchor: 'middle', fontSize: '11', fill: '#666' }, d[xKey])
                            );
                        })
                    )
                )
            );
        }

        function SimpleAreaChart({ data, dataKeys, colors, xKey, height = 220, showLabelsFor }) {
            if (!data || !data.length) return null;
            const padding = { top: 30, right: 20, bottom: 30, left: 40 };
            const chartW = 600 - padding.left - padding.right;
            const chartH = height - padding.top - padding.bottom;
            const maxVal = Math.max(...data.flatMap(d => dataKeys.map(k => d[k] || 0))) * 1.1;
            const n = data.length;
            // Down-sample dots/labels/x-axis when there are too many points
            const dotEvery = n > 120 ? Math.ceil(n / 60) : 1;
            const xLabelEvery = Math.max(1, Math.ceil(n / 12));
            const valLabelEvery = Math.max(1, Math.ceil(n / 15));

            return React.createElement('svg', { width: '100%', height: height, viewBox: `0 0 600 ${height}`, preserveAspectRatio: 'xMidYMid meet' },
                [0, 0.25, 0.5, 0.75, 1].map((tick, i) => {
                    const y = padding.top + chartH * (1 - tick);
                    return React.createElement('g', { key: i },
                        React.createElement('line', { x1: padding.left, y1: y, x2: 600 - padding.right, y2: y, stroke: '#f0f0f0', strokeDasharray: '3 3' }),
                        React.createElement('text', { x: padding.left - 5, y: y + 4, textAnchor: 'end', fontSize: '10', fill: '#999' }, Math.round(maxVal * tick))
                    );
                }),
                dataKeys.map((key, ki) => {
                    const points = data.map((d, i) => ({
                        x: padding.left + (n === 1 ? chartW / 2 : (i / (n - 1)) * chartW),
                        y: padding.top + chartH - ((d[key] || 0) / maxVal) * chartH,
                        val: d[key]
                    }));
                    const pathD = points.map((p, i) => `${i === 0 ? 'M' : 'L'} ${p.x} ${p.y}`).join(' ');
                    const areaD = pathD + ` L ${points[points.length - 1].x} ${padding.top + chartH} L ${points[0].x} ${padding.top + chartH} Z`;
                    return React.createElement('g', { key: ki },
                        React.createElement('path', { d: areaD, fill: colors[ki % colors.length], opacity: '0.12' }),
                        React.createElement('path', { d: pathD, fill: 'none', stroke: colors[ki % colors.length], strokeWidth: '2' }),
                        points.filter((_, i) => i % dotEvery === 0 || i === n - 1).map((p, i) => React.createElement('circle', { key: i, cx: p.x, cy: p.y, r: dotEvery > 1 ? '2' : '3', fill: colors[ki % colors.length] })),
                        showLabelsFor === key && points.filter((_, i) => i % valLabelEvery === 0 || i === n - 1).map((p, i) => React.createElement('g', { key: 'lbl' + i },
                            React.createElement('rect', { x: p.x - 18, y: p.y - 24, width: 36, height: 18, rx: 9, fill: colors[ki % colors.length] }),
                            React.createElement('text', { x: p.x, y: p.y - 12, textAnchor: 'middle', fontSize: '10', fill: '#fff', fontWeight: 700 }, Math.round(p.val))
                        ))
                    );
                }),
                data.map((d, i) => (i % xLabelEvery === 0 || i === n - 1) ? React.createElement('text', { key: i, x: padding.left + (n === 1 ? chartW / 2 : (i / (n - 1)) * chartW), y: height - 8, textAnchor: 'middle', fontSize: '11', fill: '#666' }, d[xKey]) : null)
            );
        }

        function SimpleComboChart({ data, xKey, lineKey, barKey, lineColor, barColor, height = 200, lineMode = 'continuous' }) {
            if (!data || !data.length) return null;
            const padding = { top: 20, right: 50, bottom: 30, left: 50 };
            const W = 600;
            const chartW = W - padding.left - padding.right;
            const chartH = height - padding.top - padding.bottom;
            const n = data.length;
            const maxLine = Math.max(1, ...data.map(d => d[lineKey] || 0)) * 1.1;
            const maxBar = Math.max(1, ...data.map(d => d[barKey] || 0)) * 1.1;
            const xLabelEvery = Math.max(1, Math.ceil(n / 12));
            const xAt = (i) => padding.left + (n === 1 ? chartW / 2 : (i / (n - 1)) * chartW);
            const barW = (n === 1 ? chartW * 0.4 : (chartW / n) * 0.6);
            const yFor = (val) => padding.top + chartH - ((val || 0) / maxLine) * chartH;

            const peakPoints = data.map((d, i) => ({ x: xAt(i), y: yFor(d[lineKey]), val: d[lineKey] || 0 }));

            let pathD;
            if (lineMode === 'sawtooth') {
                const yZero = padding.top + chartH;
                const resetDx = Math.max(2, (n > 1 ? (chartW / (n - 1)) : chartW) * 0.04);
                const segs = [];
                segs.push(`M ${peakPoints[0].x} ${peakPoints[0].y}`);
                for (let i = 0; i < n; i++) {
                    const p = peakPoints[i];
                    if (i > 0) segs.push(`L ${p.x} ${p.y}`);
                    segs.push(`L ${p.x + resetDx} ${yZero}`);
                    if (i < n - 1) segs.push(`M ${p.x + resetDx} ${yZero}`);
                }
                pathD = segs.join(' ');
            } else {
                pathD = peakPoints.map((p, i) => `${i === 0 ? 'M' : 'L'} ${p.x} ${p.y}`).join(' ');
            }

            return React.createElement('svg', { width: '100%', height: height, viewBox: `0 0 ${W} ${height}`, preserveAspectRatio: 'xMidYMid meet' },
                [0, 0.25, 0.5, 0.75, 1].map((tick, i) => {
                    const y = padding.top + chartH * (1 - tick);
                    return React.createElement('g', { key: 'g' + i },
                        React.createElement('line', { x1: padding.left, y1: y, x2: W - padding.right, y2: y, stroke: '#f0f0f0', strokeDasharray: '3 3' }),
                        React.createElement('text', { x: padding.left - 5, y: y + 4, textAnchor: 'end', fontSize: '10', fill: lineColor }, Math.round(maxLine * tick)),
                        React.createElement('text', { x: W - padding.right + 5, y: y + 4, textAnchor: 'start', fontSize: '10', fill: barColor }, Math.round(maxBar * tick))
                    );
                }),
                data.map((d, i) => {
                    const val = d[barKey] || 0;
                    const bh = (val / maxBar) * chartH;
                    const bx = xAt(i) - barW / 2;
                    const by = padding.top + chartH - bh;
                    return React.createElement('rect', { key: 'b' + i, x: bx, y: by, width: barW, height: bh, fill: barColor, rx: 4, opacity: 0.7 });
                }),
                React.createElement('path', { d: pathD, fill: 'none', stroke: lineColor, strokeWidth: 2 }),
                peakPoints.map((p, i) => React.createElement('circle', { key: 'd' + i, cx: p.x, cy: p.y, r: 3, fill: lineColor })),
                data.map((d, i) => (i % xLabelEvery === 0 || i === n - 1) ? React.createElement('text', { key: 'x' + i, x: xAt(i), y: height - 8, textAnchor: 'middle', fontSize: '11', fill: '#666' }, d[xKey]) : null)
            );
        }

        function SimplePieChart({ data, colors, size = 200 }) {
            if (!data || !data.length) return null;
            const total = data.reduce((s, d) => s + d.value, 0);
            const cx = size / 2, cy = size / 2, r = size * 0.35, ir = size * 0.22;
            let cumAngle = -Math.PI / 2;

            const slices = data.map((d, i) => {
                const angle = (d.value / total) * Math.PI * 2;
                const startAngle = cumAngle;
                cumAngle += angle;
                const endAngle = cumAngle;
                const largeArc = angle > Math.PI ? 1 : 0;
                const x1o = cx + r * Math.cos(startAngle), y1o = cy + r * Math.sin(startAngle);
                const x2o = cx + r * Math.cos(endAngle), y2o = cy + r * Math.sin(endAngle);
                const x1i = cx + ir * Math.cos(endAngle), y1i = cy + ir * Math.sin(endAngle);
                const x2i = cx + ir * Math.cos(startAngle), y2i = cy + ir * Math.sin(startAngle);
                const pathD = `M ${x1o} ${y1o} A ${r} ${r} 0 ${largeArc} 1 ${x2o} ${y2o} L ${x1i} ${y1i} A ${ir} ${ir} 0 ${largeArc} 0 ${x2i} ${y2i} Z`;
                const midAngle = startAngle + angle / 2;
                const lx = cx + (r + 20) * Math.cos(midAngle);
                const ly = cy + (r + 20) * Math.sin(midAngle);
                const pct = Math.round((d.value / total) * 100);
                return { pathD, lx, ly, pct, name: d.name, i };
            });

            return React.createElement('svg', { width: size, height: size, viewBox: `0 0 ${size} ${size}` },
                slices.map((slice) => React.createElement('g', { key: slice.i },
                    React.createElement('path', { d: slice.pathD, fill: colors[slice.i % colors.length], opacity: '0.85', title: `${slice.name}: ${data[slice.i].value}` }),
                    slice.pct > 5 && React.createElement('text', { x: slice.lx, y: slice.ly, textAnchor: 'middle', fontSize: '10', fill: '#333', fontWeight: '600' }, `${slice.name} ${slice.pct}%`)
                ))
            );
        }

