        // Resolve profile aliases (chef_f5 → chef_f1, etc.)
        function getTutorials(profileId) {
            let tutorials = TUTORIAL_REGISTRY[profileId];
            if (typeof tutorials === 'string') tutorials = TUTORIAL_REGISTRY[tutorials];
            return tutorials || [];
        }

        // ===================== METEOBLUE API CONFIG =====================
        const METEOBLUE_API_KEY = 'sWtaJy9XrwE6TAcB';
        const meteoFermes = {
            F1: { nom: 'Framboise Larache (F1)', lat: 35.08, lon: -6.14, altitude: 49, region: 'Larache' },
            F2: { nom: 'Avocat F2', lat: 35.08, lon: -6.14, altitude: 49, region: 'Larache' },
            F3: { nom: 'Avocat F3', lat: 35.08, lon: -6.14, altitude: 49, region: 'Larache' },
            F4: { nom: 'Avocat F4', lat: 35.08, lon: -6.14, altitude: 49, region: 'Larache' },
            F5: { nom: 'Myrtille/Framboise Laaouamra (F5)', lat: 35.08, lon: -6.14, altitude: 49, region: 'Laaouamra' },
            F6: { nom: 'Avocat F6', lat: 34.3425, lon: -6.5503, altitude: 120, region: 'Ain Atiq' },
            BAHIA: { nom: 'Avocat BAHIA', lat: 35.08, lon: -6.14, altitude: 49, region: 'Larache' },
            Avocatier: { nom: 'Ferme Avocatier', lat: 35.08, lon: -6.14, altitude: 49, region: 'Larache' }
        };

        const _meteoblueCache = {};
        const METEO_CACHE_TTL = 15 * 60 * 1000; // 15 min

        async function fetchMeteoblueData(fermeKey) {
            const ferme = meteoFermes[fermeKey];
            if (!ferme) return null;
            const cacheKey = ferme.lat + '_' + ferme.lon + '_' + ferme.altitude + '_basic';
            const cached = _meteoblueCache[cacheKey];
            if (cached && (Date.now() - cached.ts) < METEO_CACHE_TTL) return cached.data;
            const base = 'https://my.meteoblue.com/packages/basic-day_agro-day_basic-1h?apikey=' + METEOBLUE_API_KEY + '&lat=' + ferme.lat + '&lon=' + ferme.lon + '&asl=' + ferme.altitude + '&format=json';
            const agroHourly = 'https://my.meteoblue.com/packages/agro-1h?apikey=' + METEOBLUE_API_KEY + '&lat=' + ferme.lat + '&lon=' + ferme.lon + '&asl=' + ferme.altitude + '&format=json';
            try {
                const res = await fetch(base);
                if (!res.ok) throw new Error('API error ' + res.status);
                const data = await res.json();
                // Best-effort: enrich data_1h with shortwave_radiation + evapotranspiration if the agro-1h
                // package is included in the subscription. Silently skip on failure — the rest of the
                // tab keeps working with daily ETo / no hourly radiation.
                try {
                    const res2 = await fetch(agroHourly);
                    if (res2.ok) {
                        const extra = await res2.json();
                        if (extra && extra.data_1h) {
                            data.data_1h = Object.assign({}, data.data_1h || {}, {
                                shortwave_radiation: extra.data_1h.shortwave_radiation || extra.data_1h.shortwaveradiation,
                                evapotranspiration: extra.data_1h.evapotranspiration,
                            });
                        }
                    } else {
                        console.info('Meteoblue agro-1h not available (' + res2.status + ') — fallback sans radiation/ETo horaires.');
                    }
                } catch(e2) {
                    console.info('Meteoblue agro-1h fetch failed, fallback:', e2);
                }
                _meteoblueCache[cacheKey] = { data, ts: Date.now() };
                return data;
            } catch(e) {
                console.warn('Meteoblue API error for ' + fermeKey + ':', e);
                return null;
            }
        }

        async function fetchSprayData(fermeKey) {
            const ferme = meteoFermes[fermeKey];
            if (!ferme) return null;
            const cacheKey = ferme.lat + '_' + ferme.lon + '_' + ferme.altitude + '_spray';
            const cached = _meteoblueCache[cacheKey];
            if (cached && (Date.now() - cached.ts) < METEO_CACHE_TTL) return cached.data;
            const url = 'https://my.meteoblue.com/packages/agromodelspray-1h?apikey=' + METEOBLUE_API_KEY + '&lat=' + ferme.lat + '&lon=' + ferme.lon + '&asl=' + ferme.altitude + '&format=json';
            try {
                const res = await fetch(url);
                if (!res.ok) throw new Error('API error ' + res.status);
                const data = await res.json();
                _meteoblueCache[cacheKey] = { data, ts: Date.now() };
                return data;
            } catch(e) {
                console.warn('Meteoblue Spray API error for ' + fermeKey + ':', e);
                return null;
            }
        }

        function transformSprayData(apiData) {
            if (!apiData || !apiData.data_1h) return null;
            const times = apiData.data_1h.time || [];
            const spray = apiData.data_1h.spraywindow || [];
            // Group by day
            var parJour = {};
            times.forEach(function(t, i) {
                var dateKey = t.split(' ')[0];
                var h = parseInt(t.split(' ')[1]);
                if (!parJour[dateKey]) parJour[dateKey] = [];
                parJour[dateKey].push({ heure: h, value: spray[i] });
            });
            // Build daily summaries
            var jours = Object.keys(parJour).sort().map(function(dateKey) {
                var entries = parJour[dateKey];
                var workHours = entries.filter(function(e) { return e.heure >= 6 && e.heure <= 20; });
                var bonCount = workHours.filter(function(e) { return e.value === 1; }).length;
                var moyenCount = workHours.filter(function(e) { return e.value === 2; }).length;
                var mauvaisCount = workHours.filter(function(e) { return e.value === 0; }).length;
                // Find best spray windows (consecutive good hours)
                var fenetres = [];
                var start = null;
                workHours.forEach(function(e, idx) {
                    if (e.value === 1) {
                        if (start === null) start = e.heure;
                    } else {
                        if (start !== null) {
                            fenetres.push({ de: start, a: workHours[idx - 1].heure + 1 });
                            start = null;
                        }
                    }
                });
                if (start !== null) fenetres.push({ de: start, a: workHours[workHours.length - 1].heure + 1 });

                var d = new Date(dateKey + 'T12:00:00');
                var jourNoms = ['Dim','Lun','Mar','Mer','Jeu','Ven','Sam'];
                return {
                    dateISO: dateKey,
                    date: String(d.getDate()).padStart(2,'0') + '/' + String(d.getMonth()+1).padStart(2,'0'),
                    jourNom: jourNoms[d.getDay()],
                    isToday: dateKey === (function(){ var n=new Date(); return n.getFullYear()+'-'+String(n.getMonth()+1).padStart(2,'0')+'-'+String(n.getDate()).padStart(2,'0'); })(),
                    heures: entries,
                    bonCount: bonCount,
                    moyenCount: moyenCount,
                    mauvaisCount: mauvaisCount,
                    totalWork: workHours.length,
                    score: workHours.length > 0 ? Math.round((bonCount + moyenCount * 0.5) / workHours.length * 100) : 0,
                    fenetres: fenetres
                };
            });
            return { jours: jours };
        }

        function parsePictocode(code) {
            const map = {
                1: { condition: 'Ensoleillé', icon: 'fa-sun', color: '#F39C12' },
                2: { condition: 'Partiellement ensoleillé', icon: 'fa-cloud-sun', color: '#3498DB' },
                3: { condition: 'Partiellement nuageux', icon: 'fa-cloud-sun', color: '#3498DB' },
                4: { condition: 'Nuageux', icon: 'fa-cloud', color: '#95A5A6' },
                5: { condition: 'Brouillard', icon: 'fa-smog', color: '#BDC3C7' },
                6: { condition: 'Couvert + Bruine', icon: 'fa-cloud-rain', color: '#5DADE2' },
                7: { condition: 'Pluie', icon: 'fa-cloud-showers-heavy', color: '#2980B9' },
                8: { condition: 'Averses', icon: 'fa-cloud-showers-heavy', color: '#2980B9' },
                9: { condition: 'Neige', icon: 'fa-snowflake', color: '#85C1E9' },
                10: { condition: 'Neige fondue', icon: 'fa-cloud-meatball', color: '#85C1E9' },
                11: { condition: 'Orage', icon: 'fa-cloud-bolt', color: '#8E44AD' },
                12: { condition: 'Pluie verglaçante', icon: 'fa-icicles', color: '#5499C7' },
                13: { condition: 'Averses de neige', icon: 'fa-snowflake', color: '#85C1E9' },
                14: { condition: 'Orage avec pluie', icon: 'fa-cloud-bolt', color: '#8E44AD' },
                15: { condition: 'Brouillard bas', icon: 'fa-smog', color: '#BDC3C7' },
                16: { condition: 'Pluie légère', icon: 'fa-cloud-rain', color: '#5DADE2' },
                17: { condition: 'Neige légère', icon: 'fa-snowflake', color: '#AED6F1' },
            };
            return map[code] || { condition: 'Inconnu', icon: 'fa-question', color: '#999' };
        }

        function parseWindDir(deg) {
            const dirs = ['N','NE','E','SE','S','SO','O','NO'];
            return dirs[Math.round(deg / 45) % 8];
        }

        function transformMeteoblueData(apiData, fermeKey) {
            if (!apiData) return null;
            const dayData = apiData.data_day || {};
            const hourData = apiData.data_1h || {};
            const jourNoms = ['Dim','Lun','Mar','Mer','Jeu','Ven','Sam'];
            const jourNomsFull = ['Dimanche','Lundi','Mardi','Mercredi','Jeudi','Vendredi','Samedi'];
            const moisNoms = ['Janvier','Février','Mars','Avril','Mai','Juin','Juillet','Août','Septembre','Octobre','Novembre','Décembre'];
            // Use local date (Africa/Casablanca) instead of UTC to avoid timezone mismatch
            const now = new Date();
            const todayStr = now.getFullYear() + '-' + String(now.getMonth()+1).padStart(2,'0') + '-' + String(now.getDate()).padStart(2,'0');

            const previsions = (dayData.time || []).map(function(dateStr, i) {
                var d = new Date(dateStr + 'T12:00:00');
                var picto = parsePictocode(dayData.pictocode ? dayData.pictocode[i] : 1);
                return {
                    date: String(d.getDate()).padStart(2,'0') + '/' + String(d.getMonth()+1).padStart(2,'0'),
                    dateLong: jourNomsFull[d.getDay()] + ' ' + String(d.getDate()).padStart(2,'0') + ' ' + moisNoms[d.getMonth()],
                    dateISO: dateStr,
                    jourNom: jourNoms[d.getDay()],
                    condition: picto.condition,
                    icon: picto.icon,
                    iconColor: picto.color,
                    tMin: Math.round(dayData.temperature_min ? dayData.temperature_min[i] : 0),
                    tMax: Math.round(dayData.temperature_max ? dayData.temperature_max[i] : 0),
                    humidity: Math.round(dayData.relativehumidity_mean ? dayData.relativehumidity_mean[i] : 50),
                    vent: Math.round(dayData.windspeed_max ? dayData.windspeed_max[i] : 0),
                    ventDir: parseWindDir(dayData.winddirection ? dayData.winddirection[i] : 0),
                    precip: Math.round((dayData.precipitation ? dayData.precipitation[i] : 0) * 10) / 10,
                    uv: Math.round(dayData.uvindex ? dayData.uvindex[i] : 0),
                    eto: Math.round((dayData.evapotranspiration ? dayData.evapotranspiration[i] : 0) * 10) / 10,
                    sunrise: dayData.sunrise ? dayData.sunrise[i] : null,
                    sunset: dayData.sunset ? dayData.sunset[i] : null,
                    isToday: dateStr === todayStr
                };
            });

            var horaire = [];
            var horaireParJour = {};
            var horaire24ParJour = {};
            if (hourData.time) {
                hourData.time.forEach(function(t, i) {
                    var parts = t.includes('T') ? t.split('T') : t.split(' ');
                    var dateKey = parts[0];
                    var h = parseInt(parts[1]);
                    var picto = hourData.pictocode ? parsePictocode(hourData.pictocode[i]) : { icon: 'fa-sun', condition: 'Ensoleillé' };
                    var rawTemp = hourData.temperature ? hourData.temperature[i] : 0;
                    var rawRH = hourData.relativehumidity ? hourData.relativehumidity[i] : 50;
                    var rawSW = hourData.shortwave_radiation ? hourData.shortwave_radiation[i] : 0;
                    var rawEto = hourData.evapotranspiration ? hourData.evapotranspiration[i] : 0;
                    var entry = {
                        heure: String(h).padStart(2,'0') + ':00',
                        hour: h,
                        temp: Math.round(rawTemp),
                        tempRaw: rawTemp,
                        humidity: Math.round(rawRH),
                        humidityRaw: rawRH,
                        vent: Math.round(hourData.windspeed ? hourData.windspeed[i] : 0),
                        precip: Math.round((hourData.precipitation ? hourData.precipitation[i] : 0) * 10) / 10,
                        radiation: rawSW,
                        eto: rawEto,
                        icon: h < 7 || h > 19 ? 'fa-moon' : picto.icon,
                        condition: picto.condition,
                        feltTemp: Math.round(hourData.felttemperature ? hourData.felttemperature[i] : rawTemp),
                    };
                    // Horaire aujourd'hui (6h-20h) pour le graphique principal
                    if (dateKey === todayStr && h >= 6 && h <= 20) {
                        horaire.push(entry);
                    }
                    // Horaire par jour pour les popups (5h-22h)
                    if (h >= 5 && h <= 22) {
                        if (!horaireParJour[dateKey]) horaireParJour[dateKey] = [];
                        horaireParJour[dateKey].push(entry);
                    }
                    // Horaire 24h par jour pour le bloc Prévision extérieure
                    if (!horaire24ParJour[dateKey]) horaire24ParJour[dateKey] = [];
                    horaire24ParJour[dateKey].push(entry);
                });
            }

            var alertes = [];
            if (previsions.some(function(p) { return p.tMax >= 32; })) alertes.push({ type: 'chaleur', niveau: 'danger', icon: 'fa-temperature-high', color: 'var(--red)', titre: 'Alerte Forte Chaleur', message: 'Température max prévue de ' + Math.max.apply(null, previsions.map(function(p){return p.tMax;})) + '°C. Prévoir irrigation supplémentaire et protection des ouvriers.', jours: previsions.filter(function(p){return p.tMax >= 32;}).map(function(p){return p.dateLong;}).join(', ') });
            if (previsions.some(function(p) { return p.humidity < 40; })) alertes.push({ type: 'humidite', niveau: 'warning', icon: 'fa-droplet-slash', color: 'var(--orange)', titre: 'Humidité Très Basse', message: 'Humidité prévue sous 40%. Risque de stress hydrique. Augmenter irrigation.', jours: previsions.filter(function(p){return p.humidity < 40;}).map(function(p){return p.dateLong;}).join(', ') });
            if (previsions.some(function(p) { return p.tMin <= 8; })) alertes.push({ type: 'gel', niveau: 'danger', icon: 'fa-snowflake', color: 'var(--blue)', titre: 'Risque Température Basse', message: 'Température minimale de ' + Math.min.apply(null, previsions.map(function(p){return p.tMin;})) + '°C prévue. Risque pour framboises et myrtilles.', jours: previsions.filter(function(p){return p.tMin <= 8;}).map(function(p){return p.dateLong;}).join(', ') });
            if (previsions.some(function(p) { return p.vent >= 25; })) alertes.push({ type: 'vent', niveau: 'warning', icon: 'fa-wind', color: '#8E44AD', titre: 'Vent Fort', message: 'Rafales jusqu\'à ' + Math.max.apply(null, previsions.map(function(p){return p.vent;})) + ' km/h. Vérifier fixations tunnels et bâches.', jours: previsions.filter(function(p){return p.vent >= 25;}).map(function(p){return p.dateLong;}).join(', ') });
            if (previsions.some(function(p) { return p.uv >= 9; })) alertes.push({ type: 'uv', niveau: 'warning', icon: 'fa-sun', color: 'var(--red)', titre: 'Indice UV Élevé', message: 'Indice UV très élevé (' + Math.max.apply(null, previsions.map(function(p){return p.uv;})) + '). Protection ouvriers en plein champ.', jours: previsions.filter(function(p){return p.uv >= 9;}).map(function(p){return p.dateLong;}).join(', ') });
            if (previsions.some(function(p) { return p.precip >= 10; })) alertes.push({ type: 'pluie', niveau: 'warning', icon: 'fa-cloud-showers-heavy', color: 'var(--blue)', titre: 'Pluie Importante', message: 'Précipitations de ' + Math.max.apply(null, previsions.map(function(p){return p.precip;})) + ' mm prévues. Reporter traitements phyto.', jours: previsions.filter(function(p){return p.precip >= 10;}).map(function(p){return p.dateLong;}).join(', ') });

            return { previsions: previsions, horaire: horaire, horaireParJour: horaireParJour, horaire24ParJour: horaire24ParJour, alertes: alertes };
        }

