        // Import budget Excel — parse all sheets into BUDGET_BGF format
        function importBudgetExcel(file) {
            return new Promise((resolve, reject) => {
                const reader = new FileReader();
                reader.onload = (e) => {
                    try {
                        const wb = XLSX.read(e.target.result, { type: 'array' });
                        const sheetNameMap = {
                            'MARAVILLA GREEN CANE': 'Maravilla Green Cane',
                            'MARAVILLA LONG CANE': 'Maravilla Long Cane',
                            'CORINA': 'Corina',
                            'BREEZE': 'Breeze',
                            'CASCADE': 'Cascade',
                            'YASMIN CUT BACK': 'Yazmin Bi Cycle',
                        };
                        const result = {};
                        wb.SheetNames.forEach(sheetName => {
                            const varName = sheetNameMap[sheetName.toUpperCase().trim()] || sheetName;
                            const rows = XLSX.utils.sheet_to_json(wb.Sheets[sheetName], { header: 1, defval: '' });
                            // Find total: look for row with 'BGF' and a number
                            let total = 0;
                            for (let i = 0; i < Math.min(rows.length, 5); i++) {
                                const row = rows[i];
                                for (let j = 0; j < row.length; j++) {
                                    if (String(row[j]).toUpperCase().trim() === 'BGF' && typeof row[j+1] === 'number') {
                                        total = row[j+1];
                                        break;
                                    }
                                }
                                if (total > 0) break;
                            }
                            // Find distribution rows: look for rows after header with [week, percentage, ...]
                            const distribution = {};
                            let headerFound = false;
                            for (const row of rows) {
                                if (String(row[0] || row[1] || '').toUpperCase().includes('WEEK')) { headerFound = true; continue; }
                                if (!headerFound) continue;
                                // Handle both col A or col B for week number
                                let week, pct;
                                if (typeof row[0] === 'number' && typeof row[1] === 'number') {
                                    week = row[0]; pct = row[1];
                                } else if (typeof row[1] === 'number' && typeof row[2] === 'number') {
                                    week = row[1]; pct = row[2];
                                } else continue;
                                if (week > 0 && pct > 0) distribution[week] = pct;
                            }
                            if (total > 0 && Object.keys(distribution).length > 0) {
                                result[varName] = { total, distribution };
                            }
                        });
                        // Save to localStorage
                        localStorage.setItem('budgetBGFConfig', JSON.stringify(result));
                        // Update live BUDGET_BGF
                        Object.keys(BUDGET_BGF).forEach(k => delete BUDGET_BGF[k]);
                        Object.assign(BUDGET_BGF, BUDGET_BGF_DEFAULT, result);
                        resolve(result);
                    } catch(err) { reject(err); }
                };
                reader.onerror = reject;
                reader.readAsArrayBuffer(file);
            });
        }

        function computeBudgetWeekly(total, distribution) {
            const result = {};
            Object.entries(distribution).forEach(([week, pct]) => {
                result[Number(week)] = Math.round(total * pct);
            });
            return result;
        }

        function computeMomentum(reelByWeek, budgetByWeek, currentWeek) {
            // Exclude current week (incomplete) — only use fully completed weeks
            const lastCompleted = currentWeek - 1;
            const weights = [0.5, 0.3, 0.2];
            const ratios = [];
            const weeks = Object.keys(budgetByWeek).map(Number).sort((a, b) => a - b);
            for (let i = weeks.length - 1; i >= 0 && ratios.length < 3; i--) {
                const w = weeks[i];
                if (w > lastCompleted) continue;
                const r = reelByWeek[w] || 0;
                const b = budgetByWeek[w] || 0;
                if (b > 0 && r > 0) ratios.push(r / b);
            }
            if (ratios.length === 0) return 1;
            let totalWeight = 0, weightedSum = 0;
            ratios.forEach((ratio, i) => {
                weightedSum += ratio * weights[i];
                totalWeight += weights[i];
            });
            return weightedSum / totalWeight;
        }

        function computeProjection(reelByWeek, budgetWeekly, momentum, currentWeek) {
            // Past completed weeks: use réel. Current + future weeks: project with momentum.
            const lastCompleted = currentWeek - 1;
            const result = {};
            // Include pre-budget weeks with réel data (production started before budget)
            Object.entries(reelByWeek).forEach(([week, val]) => {
                const w = Number(week);
                if (w < currentWeek && !budgetWeekly[w]) {
                    result[w] = val;
                }
            });
            Object.entries(budgetWeekly).forEach(([week, budgetVal]) => {
                const w = Number(week);
                if (w <= lastCompleted && reelByWeek[w] !== undefined) {
                    result[w] = reelByWeek[w];
                } else if (w >= currentWeek) {
                    result[w] = Math.round(budgetVal * momentum);
                }
            });
            return result;
        }

        function computeAtterrissage(reelByWeek, budgetWeekly, momentum, currentWeek) {
            const lastCompleted = currentWeek - 1;
            let total = 0;
            // Add pre-budget réel production (weeks before budget starts)
            Object.entries(reelByWeek).forEach(([week, val]) => {
                const w = Number(week);
                if (w < currentWeek && !budgetWeekly[w]) {
                    total += val;
                }
            });
            Object.entries(budgetWeekly).forEach(([week, budgetVal]) => {
                const w = Number(week);
                if (w <= lastCompleted && reelByWeek[w] !== undefined) {
                    total += reelByWeek[w];
                } else if (w >= currentWeek) {
                    total += Math.round(budgetVal * momentum);
                }
            });
            return total;
        }

        // Get current week number (standard calendar week: Sun-Sat, matching backend & budget)
        // Get current week number (Sat-Fri, calendrier Driscoll's)
        function getCurrentWeekNumber() {
            const now = new Date();
            now.setHours(12, 0, 0, 0);
            const jan1 = new Date(now.getFullYear(), 0, 1, 12, 0, 0);
            const days = Math.floor((now - jan1) / 86400000);
            const jan1Dow = (jan1.getDay() + 1) % 7;
            return Math.ceil((days + jan1Dow + 1) / 7);
        }

        // ===================== RÉFÉRENTIEL PARCELLES UNIFIÉ =====================
