                var hourAngle = Math.acos(cosH) / rad; // degrés
                var solarNoonUTC = 12 - ferme.lon / 15; // h UTC
                var sunriseUTC = solarNoonUTC - hourAngle / 15;
                var sunsetUTC = solarNoonUTC + hourAngle / 15;
